/*Table structure for table `chat_session_detail` */

DROP TABLE IF EXISTS `chat_session_detail`;

CREATE TABLE `chat_session_detail` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '聊天会话详细ID',
  `session_id` bigint(20) NOT NULL COMMENT '聊天会话ID',
  `role` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '会话角色 user:用户 ai:AI',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '聊天内容',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_session_id` (`session_id`)
) ENGINE=InnoDB AUTO_INCREMENT=96 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='聊天会话详情表';

