(5,'张三是谁',2,'张三是中国台湾籍歌手、音乐制作人，曾作为组合“张三李四”成员活跃于乐坛 [3-4]。2021年，由他担任制作人的专辑《自本》入围第32届金曲奖最佳专辑制作人奖等8项奖项，并助力曹雅雯斩获最佳闽南语女歌手及最佳闽南语专辑奖 [4] [6]。他从业近20年，参与创作多张专辑及影视广告配乐，合作艺人包括沙宝亮、韩红等 [7]。2021年4月，他转赴大陆发展，致力于开拓华语音乐市场 [4]。','admin','2025-06-25 11:00:31','','2025-06-25 11:00:44','1'),
(6,'测试',1,'张三是中国台湾籍歌手、音乐制作人，曾作为组合“张三李四”成员活跃于乐坛 [3-4]。2021年，由他担任制作人的专辑《自本》入围第32届金曲奖最佳专辑制作人奖等8项奖项，并助力曹雅雯斩获最佳闽南语女歌手及最佳闽南语专辑奖 [4] [6]。他从业近20年，参与创作多张专辑及影视广告配乐，合作艺人包括沙宝亮、韩红等 [7]。2021年4月，他转赴大陆发展，致力于开拓华语音乐市场 [4]。','admin','2025-06-25 11:11:21','','2025-06-25 11:11:21','0');

/*Table structure for table `knowledge_base_list` */

DROP TABLE IF EXISTS `knowledge_base_list`;

CREATE TABLE `knowledge_base_list` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '知识库ID',
  `knowledge_base_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '知识库名称',
  `remark` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

