/*Table structure for table `vector_database_list` */

DROP TABLE IF EXISTS `vector_database_list`;

CREATE TABLE `vector_database_list` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '向量数据库列表ID',
  `alias_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '数据库别名',
  `host` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '数据库地址',
  `port` int(10) DEFAULT NULL COMMENT '数据库端口',
  `database` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '数据库名',
  `table` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '数据库表名称',
  `user` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '数据库用户名',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '数据库密码',
  `dimension` int(10) DEFAULT NULL COMMENT '向量纬度',
  `is_chose` tinyint(1) DEFAULT NULL COMMENT '是否选择',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

